CREATE OR REPLACE FUNCTION app_private.consume_invoice_recipes_v1(p_center_id uuid, p_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_line     RECORD;
  v_item     RECORD;
  v_recipe   UUID;
  v_total    NUMERIC(12,3);
  v_consumed INTEGER := 0;
BEGIN
  FOR v_line IN
    SELECT ii.service_id, ii.quantity AS service_qty
    FROM public.invoice_items ii
    WHERE ii.invoice_id = p_invoice_id AND ii.service_id IS NOT NULL
  LOOP
    SELECT sr.id INTO v_recipe
    FROM public.service_recipes sr
    WHERE sr.service_id = v_line.service_id
      AND sr.center_id = p_center_id
      AND sr.is_active = true
    ORDER BY sr.updated_at DESC
    LIMIT 1;

    CONTINUE WHEN v_recipe IS NULL;

    FOR v_item IN
      SELECT sri.product_id, sri.quantity AS qty, sri.unit, sri.estimated_cost
      FROM public.service_recipe_items sri
      WHERE sri.recipe_id = v_recipe
    LOOP
      v_total := round(v_item.qty * v_line.service_qty, 3);

      INSERT INTO public.inventory_consumptions
        (center_id, invoice_id, service_id, product_id, quantity, unit, unit_cost)
      VALUES
        (p_center_id, p_invoice_id, v_line.service_id, v_item.product_id,
         v_total, v_item.unit, COALESCE(v_item.estimated_cost, 0))
      ON CONFLICT (invoice_id, service_id, product_id) DO NOTHING;

      IF FOUND THEN
        -- Whole-unit, tracked consumables decrement stock with the canonical
        -- negative-stock protection.
        IF v_total = floor(v_total) THEN
          UPDATE public.products p
          SET stock_quantity = p.stock_quantity - v_total::integer
          WHERE p.id = v_item.product_id
            AND p.center_id = p_center_id
            AND p.track_inventory = true
            AND p.stock_quantity >= v_total::integer;
          IF NOT FOUND THEN
            PERFORM 1 FROM public.products p
            WHERE p.id = v_item.product_id
              AND p.center_id = p_center_id
              AND p.track_inventory = false;
            IF NOT FOUND THEN
              RAISE EXCEPTION 'insufficient_consumable_stock' USING ERRCODE = '23514';
            END IF;
          END IF;
        END IF;
        v_consumed := v_consumed + 1;
      END IF;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('consumed_lines', v_consumed);
END;
$function$

CREATE OR REPLACE FUNCTION app_private.enforce_advance_payroll_center_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
BEGIN
  IF NEW.deducted_in_run_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.payroll_runs AS run
    WHERE run.id = NEW.deducted_in_run_id AND run.center_id = NEW.center_id
  ) THEN
    RAISE EXCEPTION 'advance_payroll_run_center_mismatch' USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app_private.enforce_appointment_integrity_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status IN ('COMPLETED', 'CANCELLED', 'NO_SHOW') THEN
      RAISE EXCEPTION 'terminal_appointment_cannot_be_deleted' USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' AND NEW.status <> 'SCHEDULED' THEN
    RAISE EXCEPTION 'new_appointment_must_be_scheduled' USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.status IN ('COMPLETED', 'CANCELLED', 'NO_SHOW') AND NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'terminal_appointment_cannot_be_changed' USING ERRCODE = '23514';
    END IF;
    IF OLD.status = 'SCHEDULED' AND NEW.status NOT IN ('SCHEDULED', 'COMPLETED', 'CANCELLED', 'NO_SHOW') THEN
      RAISE EXCEPTION 'invalid_appointment_status_transition' USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.customer_id IS NULL OR NEW.employee_id IS NULL OR NEW.service_id IS NULL OR NEW.date_time IS NULL THEN
    RAISE EXCEPTION 'appointment_customer_service_staff_time_required' USING ERRCODE = '23502';
  END IF;

  PERFORM 1 FROM public.customers c
  WHERE c.id = NEW.customer_id AND c.center_id = NEW.center_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'appointment_customer_wrong_center' USING ERRCODE = '23503';
  END IF;

  PERFORM 1 FROM public.employees e
  WHERE e.id = NEW.employee_id
    AND e.center_id = NEW.center_id
    AND (NEW.status <> 'SCHEDULED' OR e.is_active = true);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'appointment_employee_not_available' USING ERRCODE = '23503';
  END IF;

  PERFORM 1 FROM public.services s
  WHERE s.id = NEW.service_id
    AND s.center_id = NEW.center_id
    AND (NEW.status <> 'SCHEDULED' OR s.is_active = true);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'appointment_service_not_available' USING ERRCODE = '23503';
  END IF;

  IF NEW.status = 'SCHEDULED' THEN
    PERFORM 1 FROM public.appointments a
    WHERE a.center_id = NEW.center_id
      AND a.employee_id = NEW.employee_id
      AND a.status = 'SCHEDULED'
      AND a.date_time = NEW.date_time
      AND a.id <> NEW.id;
    IF FOUND THEN
      RAISE EXCEPTION 'appointment_staff_time_conflict' USING ERRCODE = '23505';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app_private.enforce_appointment_integrity_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_service_duration INTEGER;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status IN ('COMPLETED', 'CANCELLED', 'NO_SHOW') THEN
      RAISE EXCEPTION 'terminal_appointment_cannot_be_deleted' USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' AND NEW.status <> 'SCHEDULED' THEN
    RAISE EXCEPTION 'new_appointment_must_be_scheduled' USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.status IN ('COMPLETED', 'CANCELLED', 'NO_SHOW') AND NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'terminal_appointment_cannot_be_changed' USING ERRCODE = '23514';
    END IF;
    IF OLD.status = 'SCHEDULED' AND NEW.status NOT IN ('SCHEDULED', 'COMPLETED', 'CANCELLED', 'NO_SHOW') THEN
      RAISE EXCEPTION 'invalid_appointment_status_transition' USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.customer_id IS NULL OR NEW.employee_id IS NULL OR NEW.service_id IS NULL OR NEW.date_time IS NULL THEN
    RAISE EXCEPTION 'appointment_customer_service_staff_time_required' USING ERRCODE = '23502';
  END IF;

  PERFORM 1 FROM public.customers AS customer
  WHERE customer.id = NEW.customer_id
    AND customer.center_id = NEW.center_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'appointment_customer_wrong_center' USING ERRCODE = '23503';
  END IF;

  PERFORM 1 FROM public.employees AS employee
  WHERE employee.id = NEW.employee_id
    AND employee.center_id = NEW.center_id
    AND (NEW.status <> 'SCHEDULED' OR employee.is_active = true);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'appointment_employee_not_available' USING ERRCODE = '23503';
  END IF;

  SELECT service.duration_minutes
  INTO v_service_duration
  FROM public.services AS service
  WHERE service.id = NEW.service_id
    AND service.center_id = NEW.center_id
    AND (NEW.status <> 'SCHEDULED' OR service.is_active = true);
  IF NOT FOUND OR v_service_duration IS NULL OR v_service_duration <= 0 THEN
    RAISE EXCEPTION 'appointment_service_not_available' USING ERRCODE = '23503';
  END IF;

  -- The database, not the client, owns the duration snapshot. Catalog edits do
  -- not reinterpret an existing booking; selecting a different service does.
  IF TG_OP = 'INSERT' THEN
    NEW.duration_minutes_snapshot := v_service_duration;
  ELSIF NEW.service_id IS DISTINCT FROM OLD.service_id
        OR OLD.duration_minutes_snapshot IS NULL THEN
    NEW.duration_minutes_snapshot := v_service_duration;
  ELSE
    NEW.duration_minutes_snapshot := OLD.duration_minutes_snapshot;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app_private.maintain_entitlement_balance_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_ent          public.customer_entitlements%ROWTYPE;
  v_balance      NUMERIC(12,3) := 0.000;
  v_redeem_total NUMERIC(12,3) := 0.000;
  v_refund_total NUMERIC(12,3) := 0.000;
  v_unit_row     public.package_entitlement_units%ROWTYPE;
  v_new_status   TEXT;
  v_has_redeem   BOOLEAN := false;
BEGIN
  SELECT * INTO v_ent
  FROM public.customer_entitlements ce
  WHERE ce.id = NEW.entitlement_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'entitlement_not_found' USING ERRCODE = '23503';
  END IF;

  IF NEW.center_id IS DISTINCT FROM v_ent.center_id THEN
    RAISE EXCEPTION 'entitlement_center_mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT
    COALESCE(SUM(CASE el.entry_type
                   WHEN 'ISSUE'      THEN  el.amount
                   WHEN 'FUND'       THEN  el.amount
                   WHEN 'ADJUSTMENT' THEN  el.amount
                   WHEN 'REDEEM'     THEN -el.amount
                   WHEN 'REFUND'     THEN -el.amount
                   ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN el.entry_type = 'REDEEM' THEN el.amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN el.entry_type = 'REFUND' THEN el.amount ELSE 0 END), 0),
    EXISTS (SELECT 1 FROM public.entitlement_ledger el2
            WHERE el2.entitlement_id = NEW.entitlement_id
              AND el2.entry_type = 'REDEEM')
  INTO v_balance, v_redeem_total, v_refund_total, v_has_redeem
  FROM public.entitlement_ledger el
  WHERE el.entitlement_id = NEW.entitlement_id;

  v_balance := round(v_balance + CASE NEW.entry_type
                   WHEN 'ISSUE'      THEN  NEW.amount
                   WHEN 'FUND'       THEN  NEW.amount
                   WHEN 'ADJUSTMENT' THEN  NEW.amount
                   WHEN 'REDEEM'     THEN -NEW.amount
                   WHEN 'REFUND'     THEN -NEW.amount
                   ELSE 0 END, 3);
  v_refund_total := v_refund_total + CASE WHEN NEW.entry_type = 'REFUND' THEN NEW.amount ELSE 0 END;

  IF v_balance < -0.0005 THEN
    RAISE EXCEPTION 'entitlement_insufficient_balance' USING ERRCODE = '23514';
  END IF;
  v_balance := GREATEST(0.000, v_balance);

  -- REDEEM with units consumes package sessions for exactly the service the
  -- entitlement was sold with, never beyond the remaining sessions.
  IF NEW.entry_type = 'REDEEM' AND NEW.units IS NOT NULL THEN
    SELECT * INTO v_unit_row
    FROM public.package_entitlement_units peu
    WHERE peu.entitlement_id = NEW.entitlement_id
      AND peu.service_id = NEW.service_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'package_service_not_included' USING ERRCODE = '23503';
    END IF;
    IF v_unit_row.used_units + NEW.units > v_unit_row.total_units THEN
      RAISE EXCEPTION 'package_insufficient_units' USING ERRCODE = '23514';
    END IF;
    UPDATE public.package_entitlement_units peu
    SET used_units = peu.used_units + NEW.units
    WHERE peu.id = v_unit_row.id;
  END IF;

  -- REFUND covers only unused remaining value.
  IF NEW.entry_type = 'REFUND' THEN
    IF NEW.amount > v_ent.remaining_value + 0.0005 THEN
      RAISE EXCEPTION 'entitlement_refund_exceeds_remaining' USING ERRCODE = '23514';
    END IF;
  END IF;

  -- VOID is a governed correction for untouched instruments only.
  IF NEW.entry_type = 'VOID' THEN
    IF v_has_redeem OR v_ent.remaining_value <> v_ent.original_value THEN
      RAISE EXCEPTION 'entitlement_void_requires_no_redemptions' USING ERRCODE = '23514';
    END IF;
  END IF;

  -- EXPIRY is the reserved, explicitly governed hook. It records the event
  -- with an actor and reason but does NOT recognize breakage: the balance
  -- stays on the books as an outstanding liability until a future governed
  -- breakage policy is enabled.
  IF NEW.entry_type = 'EXPIRY' THEN
    IF v_ent.expires_at IS NULL OR v_ent.expires_at > now() THEN
      RAISE EXCEPTION 'entitlement_not_yet_expired' USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.entry_type = 'VOID' THEN
    v_new_status := 'VOID';
  ELSIF NEW.entry_type = 'EXPIRY' THEN
    v_new_status := 'EXPIRED';
  ELSIF v_balance <= 0.0005 AND v_refund_total > 0 THEN
    v_new_status := 'REFUNDED';
  ELSIF v_balance <= 0.0005 THEN
    v_new_status := 'FULLY_REDEEMED';
  ELSIF v_redeem_total > 0 THEN
    v_new_status := 'PARTIALLY_REDEEMED';
  ELSE
    v_new_status := 'ACTIVE';
  END IF;

  UPDATE public.customer_entitlements ce
  SET remaining_value = v_balance,
      status          = v_new_status,
      updated_at      = now()
  WHERE ce.id = NEW.entitlement_id;

  -- Legacy mirror so gift_cards.current_balance stays readable by old code
  -- while remaining derived from the ledger (never written by clients).
  IF v_ent.kind = 'GIFT_CARD' AND v_ent.gift_card_id IS NOT NULL THEN
    UPDATE public.gift_cards gc
    SET current_balance = v_balance,
        is_active       = (v_balance > 0),
        updated_at      = now()
    WHERE gc.id = v_ent.gift_card_id;
  END IF;

  RETURN NEW;
END;
$function$

