CREATE OR REPLACE FUNCTION public.add_customer_notification_event_v1(p_center_id uuid, p_customer_id uuid, p_appointment_id uuid, p_channel text, p_direction text, p_template_key text, p_message_preview text, p_delivery_status text, p_sent_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_event public.customer_notification_timeline;
BEGIN
  IF NOT app_private.is_center_member(p_center_id) THEN
    RAISE EXCEPTION 'insufficient_privilege' USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM public.customers c
  WHERE c.id = p_customer_id AND c.center_id = p_center_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'customer_not_in_center' USING ERRCODE = '23503';
  END IF;

  IF p_appointment_id IS NOT NULL THEN
    PERFORM 1 FROM public.appointments a
    WHERE a.id = p_appointment_id
      AND a.center_id = p_center_id
      AND a.customer_id = p_customer_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'appointment_not_in_center' USING ERRCODE = '23503';
    END IF;
  END IF;

  INSERT INTO public.customer_notification_timeline (
    center_id, customer_id, appointment_id, channel, direction, template_key, message_preview, delivery_status, sent_at
  ) VALUES (
    p_center_id, p_customer_id, p_appointment_id,
    UPPER(COALESCE(p_channel, 'SYSTEM')),
    UPPER(COALESCE(p_direction, 'OUTBOUND')),
    NULLIF(trim(COALESCE(p_template_key, '')), ''),
    COALESCE(NULLIF(trim(COALESCE(p_message_preview, '')), ''), 'Message event'),
    UPPER(COALESCE(p_delivery_status, 'QUEUED')),
    p_sent_at
  ) RETURNING * INTO v_event;

  RETURN jsonb_build_object('event', to_jsonb(v_event));
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_create_employee_v1(p_center_id uuid, p_employee jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_row public.employees;
BEGIN
  IF p_center_id IS NULL OR NOT app_private.has_center_role(p_center_id, ARRAY['ADMIN']) THEN
    RAISE EXCEPTION 'admin_role_required' USING ERRCODE = '42501';
  END IF;
  IF length(btrim(COALESCE(p_employee->>'name', ''))) = 0 THEN
    RAISE EXCEPTION 'employee_name_required' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.employees (
    center_id, name, phone, role, salary, base_salary,
    commission_percentage, is_active
  ) VALUES (
    p_center_id,
    btrim(p_employee->>'name'),
    NULLIF(btrim(COALESCE(p_employee->>'phone', '')), ''),
    COALESCE(NULLIF(btrim(COALESCE(p_employee->>'role', '')), ''), 'Staff'),
    COALESCE((p_employee->>'salary')::NUMERIC, 0),
    COALESCE((p_employee->>'baseSalary')::NUMERIC, (p_employee->>'salary')::NUMERIC, 0),
    COALESCE((p_employee->>'commissionPercentage')::NUMERIC, 0),
    COALESCE((p_employee->>'isActive')::BOOLEAN, TRUE)
  ) RETURNING * INTO v_row;
  RETURN jsonb_build_object('employee', to_jsonb(v_row));
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_employee_v1(p_center_id uuid, p_employee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_deactivated UUID;
BEGIN
  IF p_center_id IS NULL OR NOT app_private.has_center_role(p_center_id, ARRAY['ADMIN']) THEN
    RAISE EXCEPTION 'admin_role_required' USING ERRCODE = '42501';
  END IF;
  -- Legacy clients may still call the old delete-named RPC. Preserve history by
  -- converting that request to the supported lifecycle operation.
  UPDATE public.employees
  SET is_active = FALSE, updated_at = now()
  WHERE id = p_employee_id AND center_id = p_center_id
  RETURNING id INTO v_deactivated;
  IF v_deactivated IS NULL THEN
    RAISE EXCEPTION 'employee_not_found' USING ERRCODE = 'P0002';
  END IF;
  RETURN jsonb_build_object('deactivated_employee_id', v_deactivated);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_employee_v1(p_center_id uuid, p_employee_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_row public.employees;
BEGIN
  IF p_center_id IS NULL OR NOT app_private.has_center_role(p_center_id, ARRAY['ADMIN']) THEN
    RAISE EXCEPTION 'admin_role_required' USING ERRCODE = '42501';
  END IF;
  IF p_patch ? 'name' AND length(btrim(COALESCE(p_patch->>'name', ''))) = 0 THEN
    RAISE EXCEPTION 'employee_name_required' USING ERRCODE = '22023';
  END IF;
  UPDATE public.employees e
  SET
    name = CASE WHEN p_patch ? 'name' THEN btrim(p_patch->>'name') ELSE e.name END,
    phone = CASE WHEN p_patch ? 'phone' THEN NULLIF(btrim(COALESCE(p_patch->>'phone', '')), '') ELSE e.phone END,
    role = CASE WHEN p_patch ? 'role' THEN COALESCE(NULLIF(btrim(p_patch->>'role'), ''), e.role) ELSE e.role END,
    salary = CASE WHEN p_patch ? 'salary' THEN (p_patch->>'salary')::NUMERIC ELSE e.salary END,
    base_salary = CASE WHEN p_patch ? 'baseSalary' THEN (p_patch->>'baseSalary')::NUMERIC ELSE e.base_salary END,
    commission_percentage = CASE WHEN p_patch ? 'commissionPercentage' THEN (p_patch->>'commissionPercentage')::NUMERIC ELSE e.commission_percentage END,
    is_active = CASE WHEN p_patch ? 'isActive' THEN (p_patch->>'isActive')::BOOLEAN ELSE e.is_active END
  WHERE e.id = p_employee_id AND e.center_id = p_center_id
  RETURNING * INTO v_row;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'employee_not_found' USING ERRCODE = 'P0002';
  END IF;
  RETURN jsonb_build_object('employee', to_jsonb(v_row));
END;
$function$

CREATE OR REPLACE FUNCTION public.create_accounting_journal_entry_v1(p_center_id uuid, p_entry_date date, p_entry_type text, p_reference_type text, p_reference_id uuid, p_description text, p_debit_account text, p_credit_account text, p_amount numeric, p_currency text DEFAULT 'OMR'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
BEGIN
  IF p_center_id IS NULL OR NOT app_private.has_center_role(p_center_id, ARRAY['ADMIN']) THEN
    RAISE EXCEPTION 'admin_role_required' USING ERRCODE = '42501';
  END IF;
  RETURN public.create_accounting_journal_entry_admin_impl_v1(
    p_center_id, p_entry_date, p_entry_type, p_reference_type, p_reference_id,
    p_description, p_debit_account, p_credit_account, p_amount, p_currency
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_ai_booking_lead_admin_impl_v1(p_center_id uuid, p_customer_name text, p_customer_phone text, p_preferred_service_id uuid, p_preferred_date timestamp with time zone, p_source_channel text, p_summary text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_lead public.ai_booking_leads;
BEGIN
  IF NOT app_private.is_center_member(p_center_id) THEN
    RAISE EXCEPTION 'insufficient_privilege' USING ERRCODE = '42501';
  END IF;

  IF p_preferred_service_id IS NOT NULL THEN
    PERFORM 1 FROM public.services s
    WHERE s.id = p_preferred_service_id AND s.center_id = p_center_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'service_not_in_center' USING ERRCODE = '23503';
    END IF;
  END IF;

  INSERT INTO public.ai_booking_leads (
    center_id, customer_name, customer_phone, preferred_service_id, preferred_date, source_channel, summary
  ) VALUES (
    p_center_id,
    COALESCE(NULLIF(trim(COALESCE(p_customer_name, '')), ''), 'Guest lead'),
    NULLIF(trim(COALESCE(p_customer_phone, '')), ''),
    p_preferred_service_id,
    p_preferred_date,
    UPPER(COALESCE(p_source_channel, 'WEB')),
    NULLIF(trim(COALESCE(p_summary, '')), '')
  ) RETURNING * INTO v_lead;

