CREATE OR REPLACE FUNCTION public.create_payroll_run_v1(p_center_id uuid, p_period_month text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_run public.payroll_runs;
  v_lines JSONB;
  v_year INTEGER;
  v_month INTEGER;
  v_month_start TIMESTAMPTZ;
  v_month_end TIMESTAMPTZ;
BEGIN
  IF p_center_id IS NULL OR NOT app_private.has_center_role(p_center_id, ARRAY['ADMIN']) THEN
    RAISE EXCEPTION 'admin_role_required' USING ERRCODE = '42501';
  END IF;
  IF p_period_month IS NULL OR p_period_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
    RAISE EXCEPTION 'invalid_payroll_period' USING ERRCODE = '22023';
  END IF;

  v_year := split_part(p_period_month, '-', 1)::INTEGER;
  v_month := split_part(p_period_month, '-', 2)::INTEGER;
  v_month_start := make_timestamptz(v_year, v_month, 1, 0, 0, 0, 'UTC');
  v_month_end := v_month_start + INTERVAL '1 month';

  INSERT INTO public.payroll_runs (center_id, period_month, notes)
  VALUES (p_center_id, p_period_month, NULLIF(btrim(COALESCE(p_notes, '')), ''))
  RETURNING * INTO v_run;

  WITH approved_advances AS (
    SELECT employee_id, round(COALESCE(sum(amount), 0), 3) AS amount
    FROM public.employee_advances
    WHERE center_id = p_center_id
      AND status = 'APPROVED'
      AND advance_date >= v_month_start
      AND advance_date < v_month_end
    GROUP BY employee_id
  ), inserted AS (
    INSERT INTO public.payroll_line_items (
      center_id, payroll_run_id, employee_id,
      base_salary, advances_deducted, net_salary
    )
    SELECT
      p_center_id,
      v_run.id,
      employee.id,
      round(COALESCE(employee.base_salary, employee.salary, 0), 3),
      round(COALESCE(advance.amount, 0), 3),
      round(greatest(
        COALESCE(employee.base_salary, employee.salary, 0) - COALESCE(advance.amount, 0),
        0
      ), 3)
    FROM public.employees employee
    LEFT JOIN approved_advances advance ON advance.employee_id = employee.id
    WHERE employee.center_id = p_center_id AND employee.is_active = TRUE
    ORDER BY employee.name
    RETURNING *
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(inserted) ORDER BY inserted.created_at, inserted.id), '[]'::jsonb)
  INTO v_lines
  FROM inserted;

  UPDATE public.employee_advances
  SET status = 'DEDUCTED', deducted_in_run_id = v_run.id
  WHERE center_id = p_center_id
    AND status = 'APPROVED'
    AND advance_date >= v_month_start
    AND advance_date < v_month_end;

  RETURN jsonb_build_object('run', to_jsonb(v_run), 'lines', v_lines);
EXCEPTION
  WHEN unique_violation THEN
    RAISE EXCEPTION 'payroll_period_already_exists' USING ERRCODE = '23505';
END;
$function$

CREATE OR REPLACE FUNCTION public.create_service_file_admin_impl_v1(p_center_id uuid, p_customer_id uuid, p_appointment_id uuid, p_service_id uuid, p_title text, p_note text, p_before_images text[] DEFAULT ARRAY[]::text[], p_after_images text[] DEFAULT ARRAY[]::text[], p_reference_images text[] DEFAULT ARRAY[]::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_file public.service_files;
  v_image TEXT;
  v_index INTEGER := 0;
BEGIN
  IF NOT app_private.is_center_member(p_center_id) THEN
    RAISE EXCEPTION 'insufficient_privilege' USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM public.customers c
  WHERE c.id = p_customer_id AND c.center_id = p_center_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'customer_not_in_center' USING ERRCODE = '23503';
  END IF;

  IF p_appointment_id IS NOT NULL THEN
    PERFORM 1 FROM public.appointments a
    WHERE a.id = p_appointment_id
      AND a.center_id = p_center_id
      AND a.customer_id = p_customer_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'appointment_not_in_center' USING ERRCODE = '23503';
    END IF;
  END IF;

  IF p_service_id IS NOT NULL THEN
    PERFORM 1 FROM public.services s
    WHERE s.id = p_service_id AND s.center_id = p_center_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'service_not_in_center' USING ERRCODE = '23503';
    END IF;
  END IF;

  INSERT INTO public.service_files (
    center_id, customer_id, appointment_id, service_id, title, note, created_by
  ) VALUES (
    p_center_id, p_customer_id, p_appointment_id, p_service_id,
    COALESCE(NULLIF(trim(p_title), ''), 'Service File'),
    NULLIF(trim(COALESCE(p_note, '')), ''),
    auth.uid()
  ) RETURNING * INTO v_file;

  v_index := 0;
  FOREACH v_image IN ARRAY COALESCE(p_before_images, ARRAY[]::TEXT[]) LOOP
    INSERT INTO public.service_file_images (center_id, service_file_id, image_kind, image_url, sort_order)
    VALUES (p_center_id, v_file.id, 'BEFORE', v_image, v_index);
    v_index := v_index + 1;
  END LOOP;

  v_index := 0;
  FOREACH v_image IN ARRAY COALESCE(p_after_images, ARRAY[]::TEXT[]) LOOP
    INSERT INTO public.service_file_images (center_id, service_file_id, image_kind, image_url, sort_order)
    VALUES (p_center_id, v_file.id, 'AFTER', v_image, v_index);
    v_index := v_index + 1;
  END LOOP;

  v_index := 0;
  FOREACH v_image IN ARRAY COALESCE(p_reference_images, ARRAY[]::TEXT[]) LOOP
    INSERT INTO public.service_file_images (center_id, service_file_id, image_kind, image_url, sort_order)
    VALUES (p_center_id, v_file.id, 'REFERENCE', v_image, v_index);
    v_index := v_index + 1;
  END LOOP;

  RETURN jsonb_build_object('service_file', to_jsonb(v_file));
END;
$function$

