 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.transition_visit_v1(p_center_id uuid, p_appointment_id uuid, p_stage text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_appointment public.appointments%ROWTYPE;
  v_current     TEXT;
  v_valid       BOOLEAN := false;
BEGIN
  IF p_center_id IS NULL OR NOT app_private.is_center_member(p_center_id) THEN
    RAISE EXCEPTION 'not_authorized_for_center' USING ERRCODE = '42501';
  END IF;
  IF p_stage NOT IN ('BOOKED', 'CONFIRMED', 'ARRIVED', 'IN_SERVICE', 'READY_FOR_CHECKOUT') THEN
    RAISE EXCEPTION 'invalid_visit_stage' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_appointment
  FROM public.appointments a
  WHERE a.id = p_appointment_id AND a.center_id = p_center_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'appointment_not_found' USING ERRCODE = '23503';
  END IF;

  IF v_appointment.status <> 'SCHEDULED' THEN
    RAISE EXCEPTION 'appointment_not_scheduled' USING ERRCODE = '23514';
  END IF;

  v_current := COALESCE(v_appointment.visit_stage::text, 'BOOKED');

  IF v_current = 'BOOKED' THEN
    v_valid := p_stage IN ('CONFIRMED', 'ARRIVED');
  ELSIF v_current = 'CONFIRMED' THEN
    v_valid := p_stage = 'ARRIVED';
  ELSIF v_current = 'ARRIVED' THEN
    v_valid := p_stage = 'IN_SERVICE';
  ELSIF v_current = 'IN_SERVICE' THEN
    v_valid := p_stage = 'READY_FOR_CHECKOUT';
  ELSIF v_current = 'READY_FOR_CHECKOUT' THEN
    v_valid := p_stage = 'IN_SERVICE';
  END IF;

  IF NOT v_valid THEN
    RAISE EXCEPTION 'invalid_visit_transition' USING ERRCODE = '23514';
  END IF;

  UPDATE public.appointments a
  SET visit_stage = p_stage::public.visit_stage,
      started_at  = CASE WHEN p_stage = 'IN_SERVICE'
                         THEN COALESCE(a.started_at, now()) ELSE a.started_at END,
      updated_at  = now()
  WHERE a.id = p_appointment_id;

  RETURN jsonb_build_object(
    'appointment_id', p_appointment_id,
    'stage', p_stage
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.void_entitlement_admin_impl_v1(p_entitlement_id uuid, p_reason text, p_actor_employee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_ent public.customer_entitlements%ROWTYPE;
  v_center_id UUID;
BEGIN
  IF length(btrim(COALESCE(p_reason, ''))) = 0 THEN
    RAISE EXCEPTION 'void_reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ent
  FROM public.customer_entitlements ce
  WHERE ce.id = p_entitlement_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'entitlement_not_found' USING ERRCODE = '23503';
  END IF;
  v_center_id := v_ent.center_id;

  IF NOT app_private.is_center_member(v_center_id) THEN
    RAISE EXCEPTION 'unauthorized_entitlement_center' USING ERRCODE = '42501';
  END IF;

  IF p_actor_employee_id IS NULL THEN
    RAISE EXCEPTION 'void_actor_required' USING ERRCODE = '23502';
  END IF;
  PERFORM 1 FROM public.employees e
  WHERE e.id = p_actor_employee_id AND e.center_id = v_center_id AND e.is_active = true;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'void_actor_not_available' USING ERRCODE = '23503';
  END IF;

  INSERT INTO public.entitlement_ledger (
    center_id, entitlement_id, entry_type, amount, actor_id, reason
  ) VALUES (
    v_center_id, v_ent.id, 'VOID', 0, p_actor_employee_id,
    'Void: ' || btrim(p_reason)
  );

  RETURN jsonb_build_object('entitlement_id', v_ent.id, 'status', 'VOID');
END;
$function$

CREATE OR REPLACE FUNCTION public.void_entitlement_v1(p_entitlement_id uuid, p_reason text, p_actor_employee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_center_id UUID;
BEGIN
  SELECT center_id INTO v_center_id
  FROM public.customer_entitlements
  WHERE id = p_entitlement_id;
  IF v_center_id IS NULL OR NOT app_private.has_center_role(v_center_id, ARRAY['ADMIN']) THEN
    RAISE EXCEPTION 'admin_role_required' USING ERRCODE = '42501';
  END IF;
  RETURN public.void_entitlement_admin_impl_v1(
    p_entitlement_id, p_reason, p_actor_employee_id
  );
END;
$function$
